def to_cents(price):
    if "." not in price:
        return int(price) * 100
    whole, part = price.split(".")
    return int(whole) * 100 + int(part.ljust(2, "0"))

def add_prices(prices):
    total = sum(to_cents(p) for p in prices)
    return "%d.%02d" % divmod(total, 100)

def to_cents(price):
    whole, point, part = price.partition(".")
    cents = int(part[:2].ljust(2, "0")) if point else 0
    return int(whole) * 100 + cents

def add_prices(prices):
    total = 0
    for p in prices:
        total += to_cents(p)
    dollars, cents = divmod(total, 100)
    return str(dollars) + "." + str(cents).rjust(2, "0")
